// Release manifest is generated by scripts/release.mjs. Keep this file outside its own hash.
const BUILD='f9b3e0d3a07fa50c';
const CACHE='swamp-muppet-'+BUILD;
const ASSETS=['./','./index.html','./styles.css','./app.js','./camera.js','./model.js','./storage.js','./reader.js','./manifest.webmanifest','./icons/rex-phoenix-v1-192.png','./icons/rex-phoenix-v1-512.png','./icons/rex-phoenix-v1-maskable-512.png'];
const base=new URL('./',self.location.href);
// Static hosts may redirect index.html to /. A redirected Response cannot be
// replayed for browser navigation (redirect mode manual); retain its bytes,
// status and content type, but not its redirect history.
async function navigationSafe(response){
 if(!response?.redirected)return response;
 if(new URL(response.url).origin!==base.origin)throw Error('Asset redirected outside this app');
 const headers=new Headers(response.headers);headers.delete('content-length');headers.delete('content-encoding');
 return new Response(await response.blob(),{status:response.status,statusText:response.statusText,headers});
}
self.addEventListener('install',event=>event.waitUntil((async()=>{
 const before=await fetch(new URL('version.json',base),{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Version unavailable');return r.json();});
 if(before.build!==BUILD)throw Error('Release changed during installation');
 const cache=await caches.open(CACHE);
 try{await Promise.all(ASSETS.map(async path=>{const url=new URL(path,base),response=await fetch(url,{cache:'reload'});if(!response.ok)throw Error('Incomplete release');await cache.put(url,await navigationSafe(response));}));
 const after=await fetch(new URL('version.json',base),{cache:'no-store'}).then(r=>r.json());if(after.build!==BUILD)throw Error('Release changed during installation');}
 catch(error){await caches.delete(CACHE);throw error;}
 // No unconditional skipWaiting: the app coordinates safe activation across clients.
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key!==CACHE&&(key.startsWith('swamp-muppet-')||/^swamp-fish-v\d+$/.test(key)))await caches.delete(key);await self.clients.claim();})()));
let ballot=null;
self.addEventListener('message',event=>{
 if(event.data?.type==='REQUEST_ACTIVATION')event.waitUntil((async()=>{
  const clients=(await self.clients.matchAll({type:'window',includeUncontrolled:true})).filter(c=>c.url.startsWith(base.href));
  if(!clients.length){await self.skipWaiting();return;}
  const token=crypto.randomUUID();ballot={token,remaining:new Set(clients.map(c=>c.id)),denied:false,expires:Date.now()+10000};
  for(const client of clients)client.postMessage({type:'CAN_ACTIVATE',token});
 })());
 if(event.data?.type==='ACTIVATION_VOTE'&&ballot&&event.data.token===ballot.token&&Date.now()<ballot.expires){
  if(!event.source?.id||!ballot.remaining.has(event.source.id))return;
  ballot.remaining.delete(event.source.id);if(event.data.safe!==true)ballot.denied=true;
  if(!ballot.remaining.size&&!ballot.denied){ballot=null;event.waitUntil(self.skipWaiting());}
 }
});
self.addEventListener('fetch',event=>{
 const url=new URL(event.request.url);
 if(event.request.method!=='GET'||url.origin!==base.origin||!url.href.startsWith(base.href)||url.pathname.endsWith('/sw.js')||url.pathname.endsWith('/version.json'))return;
 event.respondWith((async()=>{const cache=await caches.open(CACHE);if(event.request.mode==='navigate'){const page=await cache.match(new URL('index.html',base));return page?navigationSafe(page):fetch(event.request);}const hit=await cache.match(event.request,{ignoreSearch:false});return hit||fetch(event.request);})());
});
